function applyClipPreviewTransform(el,c){if(!el||!c)return;const targetAspect=state.width/state.height,srcAspect=(c.width||state.width)/(c.height||state.height);let fw=100,fh=100;if(srcAspect>targetAspect)fh=100*targetAspect/srcAspect;else fw=100*srcAspect/targetAspect;el.style.position='absolute';el.style.left=`${c.x??50}%`;el.style.top=`${c.y??50}%`;el.style.width=`${fw}%`;el.style.height=`${fh}%`;el.style.objectFit='fill';el.style.transform=`translate(-50%,-50%) rotate(${c.rotation??0}deg) scale(${c.scale??1})`;el.style.opacity=String(c.opacity??1);el.style.transformOrigin='50% 50%'}
function selectedPreviewTarget(){if(!state.selected)return null;if(state.selected.type==='layer'){const o=state.layers.find(x=>x.id===state.selected.id);if(!o||o.type==='solid'||state.time<o.start||state.time>o.start+o.duration)return null;return{el:els.layers.querySelector(`[data-layer="${o.id}"]`),model:o}}const p=previewAt(state.time);if(!p)return null;if(p.primary.clip.id===state.selected.id){const c=p.primary.clip,el=c.kind==='gif'&&!c.previewUrl?els.gif:els.video;return{el,model:c}}if(p.secondary?.clip.id===state.selected.id){const c=p.secondary.clip,el=c.kind==='gif'&&!c.previewUrl?els.gifB:els.videoB;return{el,model:c}}return null}
function updateTransformBox(){requestAnimationFrame(()=>{const t=selectedPreviewTarget();if(!t?.el||t.el.classList.contains('hidden')){els.transformBox.classList.add('hidden');return}const sr=els.screen.getBoundingClientRect(),tr=t.el.getBoundingClientRect();if(!tr.width||!tr.height){els.transformBox.classList.add('hidden');return}const scale=Math.max(.001,t.model.scale??1),w=t.el.offsetWidth*scale,h=t.el.offsetHeight*scale,cx=tr.left+tr.width/2-sr.left,cy=tr.top+tr.height/2-sr.top;els.transformBox.classList.remove('hidden');els.transformBox.style.left=`${cx}px`;els.transformBox.style.top=`${cy}px`;els.transformBox.style.width=`${w}px`;els.transformBox.style.height=`${h}px`;els.transformBox.style.transform=`translate(-50%,-50%) rotate(${t.model.rotation??0}deg)`})}
