function setTimelineZoom(value,center=true){const z=$('#zoom'),next=clamp(Number(value),Number(z.min),Number(z.max));z.value=String(next);renderTimeline();requestAnimationFrame(()=>{if(!center)return;const sc=$('#timelineScroll'),ratio=clamp(state.time/Math.max(total(),.001),0,1),x=72+(els.inner.clientWidth-72)*ratio;sc.scrollLeft=clamp(x-sc.clientWidth/2,0,Math.max(0,sc.scrollWidth-sc.clientWidth))})}
