$('#play').onclick=play;$('#start').onclick=()=>seek(0);$('#end').onclick=()=>seek(total());$('#zoom').oninput=e=>setTimelineZoom(e.target.value);$('#zoomOut').onclick=()=>setTimelineZoom(Number($('#zoom').value)/1.25);$('#zoomIn').onclick=()=>setTimelineZoom(Number($('#zoom').value)*1.25);$('#zoomFit').onclick=fitTimeline;$('#timelineScroll').addEventListener('wheel',e=>{if(!e.ctrlKey&&!e.metaKey)return;e.preventDefault();setTimelineZoom(Number($('#zoom').value)*(e.deltaY>0?.88:1.14))},{passive:false});
function setAssetView(view){state.mediaView=view;els.mediaView.classList.toggle('hidden',view!=='media');els.shapeView.classList.toggle('hidden',view!=='shapes');els.transitionView.classList.toggle('hidden',view!=='transitions');els.giphyView.classList.toggle('hidden',view!=='giphy');document.querySelectorAll('.tool').forEach(x=>x.classList.remove('active'));if(view==='media')$('#mediaTool').classList.add('active');if(view==='shapes')$('#shapeTool').classList.add('active');if(view==='transitions')$('#transitionTool').classList.add('active');if(view==='giphy')$('#giphyTool').classList.add('active')}
function giphyKey(){return GIPHY_BUILTIN_KEY||localStorage.getItem('exportToVideo:giphyKey')||$('#giphyKey')?.value.trim()||''}
function updateGiphyChrome(){const hasKey=!!giphyKey();$('#giphyKeySetup').classList.toggle('hidden',hasKey);$('#giphySearchRow').classList.toggle('hidden',state.giphyMode!=='search');$('#giphyTrendingTab').classList.toggle('active',state.giphyMode==='trending');$('#giphySearchTab').classList.toggle('active',state.giphyMode==='search');document.querySelectorAll('[data-giphy-type]').forEach(b=>b.classList.toggle('active',b.dataset.giphyType===state.giphyType));$('#giphySectionTitle').textContent=(state.giphyMode==='trending'?'Tendencias':'Resultados')+' · '+(state.giphyType==='stickers'?'Stickers':'GIFs')+(GIPHY_BUILTIN_KEY?' · Conectado':'')}
function renderGiphyResults(items,append=false){const html=items.map(g=>{const original=g.images?.original?.url||'',thumb=g.images?.fixed_width_small?.url||g.images?.fixed_width?.url||original;if(!original||!thumb)return'';return`<button draggable="true" class="giphy-card" data-giphy-url="${esc(original)}" data-giphy-title="${esc(g.title||'giphy')}.gif"><img loading="lazy" src="${esc(thumb)}" alt="${esc(g.title||'GIF')}"><span>＋</span></button>`}).join('');if(append)els.giphyResults.insertAdjacentHTML('beforeend',html);else els.giphyResults.innerHTML=html||'<p class="muted centertext">Sin resultados.</p>';if(items.length>=24){els.giphyResults.insertAdjacentHTML('beforeend','<button id="giphyMore" class="giphy-more">Cargar más</button>')}}
async function loadGiphy({reset=true}={}){const key=giphyKey();updateGiphyChrome();if(!key){els.giphyResults.innerHTML='<div class="giphy-empty"><strong>Conecta GIPHY</strong><span>Guarda una API key gratuita para ver tendencias, buscar GIFs y stickers.</span></div>';return}if(state.giphyBusy)return;if(reset){state.giphyOffset=0;state.giphyHasMore=true;els.giphyResults.innerHTML='<p class="muted centertext">Cargando…</p>'}state.giphyBusy=true;try{const type=state.giphyType==='stickers'?'stickers':'gifs',mode=state.giphyMode,q=$('#giphyQuery')?.value.trim()||'';if(mode==='search'&&!q){els.giphyResults.innerHTML='<p class="muted centertext">Escribe algo para buscar.</p>';return}const endpoint=mode==='trending'?`https://api.giphy.com/v1/${type}/trending?api_key=${encodeURIComponent(key)}&limit=24&offset=${state.giphyOffset}&rating=g`:`https://api.giphy.com/v1/${type}/search?api_key=${encodeURIComponent(key)}&q=${encodeURIComponent(q)}&limit=24&offset=${state.giphyOffset}&rating=g&lang=es`;const res=await fetch(endpoint);if(!res.ok)throw new Error('HTTP '+res.status);const data=await res.json(),items=data.data||[];state.giphyHasMore=items.length===24;renderGiphyResults(items,!reset);state.giphyOffset+=items.length;updateGiphyChrome()}catch(e){if(reset)els.giphyResults.innerHTML='<p class="muted centertext">No se pudo consultar GIPHY.</p>';toast('GIPHY: '+(e?.message||e),'error')}finally{state.giphyBusy=false}}
async function searchGiphy(){state.giphyMode='search';await loadGiphy({reset:true})}
async function addGiphy(url,title){toast('Descargando GIF…');try{const r=await fetch(url);if(!r.ok)throw new Error('HTTP '+r.status);const blob=await r.blob(),file=new File([blob],(title||'giphy.gif').replace(/[^a-z0-9._-]+/gi,'_'),{type:'image/gif'});await addGifLayer(file,title||'GIPHY sticker')}catch(e){toast('No pude añadir ese GIF: '+(e?.message||e),'error')}}
$('#mediaTool').onclick=()=>{setAssetView('media');};
$('#shapeTool').onclick=()=>setAssetView('shapes');$('#transitionTool').onclick=()=>setAssetView('transitions');$('#giphyTool').onclick=()=>{setAssetView('giphy');$('#giphyKey').value=localStorage.getItem('exportToVideo:giphyKey')||'';state.giphyMode='trending';state.giphyType='gifs';updateGiphyChrome();loadGiphy({reset:true})};$('#giphyTrendingTab').onclick=()=>{state.giphyMode='trending';loadGiphy({reset:true})};$('#giphySearchTab').onclick=()=>{state.giphyMode='search';updateGiphyChrome();setTimeout(()=>$('#giphyQuery').focus(),0)};document.querySelectorAll('[data-giphy-type]').forEach(b=>b.onclick=()=>{state.giphyType=b.dataset.giphyType;loadGiphy({reset:true})});$('#giphySearch').onclick=searchGiphy;$('#giphyQuery').addEventListener('keydown',e=>{if(e.key==='Enter')searchGiphy()});$('#saveGiphyKey').onclick=()=>{const k=$('#giphyKey').value.trim();if(!k)return;localStorage.setItem('exportToVideo:giphyKey',k);toast('GIPHY conectado. Cargando tendencias…','ok');state.giphyMode='trending';state.giphyType='gifs';loadGiphy({reset:true})};
function syncExportPreview(){const a=previewAt(state.time)?.primary;if(!a){els.exportPreview.removeAttribute('src');els.exportPreviewGif.removeAttribute('src');els.exportPreview.classList.remove('hidden');els.exportPreviewGif.classList.add('hidden');return}const c=a.clip,url=c.previewUrl||c.url;if(c.kind==='gif'&&!c.previewUrl){els.exportPreview.classList.add('hidden');els.exportPreviewGif.classList.remove('hidden');els.exportPreviewGif.src=url}else{els.exportPreviewGif.classList.add('hidden');els.exportPreview.classList.remove('hidden');els.exportPreview.src=url;els.exportPreview.onloadedmetadata=()=>{try{els.exportPreview.currentTime=c.in+a.local}catch{}}}}
function closeExport(){if(!state.busy)els.drawer.classList.remove('open')}
$('#exportBtn').onclick=()=>{els.drawer.classList.add('open');renderMeta();syncExportPreview()};$('#closeDrawer').onclick=closeExport;$('#cancelExport').onclick=closeExport;els.drawer.onclick=e=>{if(e.target===els.drawer)closeExport()};$('#format').onchange=e=>state.format=e.target.value;$('#res').onchange=e=>[state.width,state.height]=e.target.value.split('x').map(Number);$('#fps').onchange=e=>state.fps=Number(e.target.value);$('#quality').onchange=e=>state.quality=Number(e.target.value);els.renderBtn.onclick=renderProject;
$('#clearBtn').onclick=()=>{if(state.busy)return;state.clips.forEach(c=>{URL.revokeObjectURL(c.url);if(c.previewUrl)URL.revokeObjectURL(c.previewUrl)});state.clips=[];state.layers.forEach(o=>{if(o.type==='gif'&&o.url)URL.revokeObjectURL(o.url)});state.layers=[];state.selected=null;state.time=0;state.rangeIn=0;state.rangeOut=null;stop();els.previewMsg.textContent='';render();syncPreview(true)};
$('#markInBtn').onclick=markIn;$('#markOutBtn').onclick=markOut;$('#clearRangeBtn').onclick=clearRange;$('#splitBtn').onclick=splitAtPlayhead;
window.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;if(e.code==='Space'){e.preventDefault();play()}if(e.code==='ArrowLeft')seek(state.time-(e.shiftKey?1:1/state.fps));if(e.code==='ArrowRight')seek(state.time+(e.shiftKey?1:1/state.fps));if(e.key.toLowerCase()==='i')markIn();if(e.key.toLowerCase()==='o')markOut();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='b'){e.preventDefault();splitAtPlayhead()}});
render();
